#!/usr/bin/env bash
# Standalone focused checks; canonical compiled imports are only read.
set -euo pipefail
repo="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)"
: "${ELAN_HOME:?Set ELAN_HOME to the pinned Lean 4.33.1 elan directory}"
export PATH="$ELAN_HOME/bin:$PATH"
: "${NLS_REFERENCE_CHECKOUT:?Set NLS_REFERENCE_CHECKOUT to the read-only compiled reference checkout}"
reference="$(cd -- "$NLS_REFERENCE_CHECKOUT" && pwd)"
build="${KDVC_BUILD_DIR:-$repo/.lake/article-checks/kdv-convexity}"
build="$(realpath -m -- "$build")"
if [[ "$build" == "$reference/.lake" || "$build" == "$reference/.lake/"* ]]; then
  echo 'Refusing to write article build output inside the reference cache.' >&2
  exit 1
fi
lean_bin="$ELAN_HOME/toolchains/leanprover--lean4---v4.33.1/bin/lean"
[[ -x "$lean_bin" ]]
if [[ -L "$build/lib/NLS/KdV" ]]; then
  echo "Refusing shared-library output through a linked KdV import directory." >&2
  exit 1
fi
mkdir -p -- "$build/lib/NLS/KdV" "$build/lib/NLS/Articles/KdVConvexity" "$build/logs"
# Shared namespaces with new local modules use real private directories.
# Reference files are linked only as imports, never as compilation targets.
for namespace in ZakharovShabat ComplexAnalysis FunctionalAnalysis SequenceSpaces Fourier DifferentialPolynomial MKdV; do
  if [[ -L "$build/lib/NLS/$namespace" ]]; then
    unlink -- "$build/lib/NLS/$namespace"
  fi
  mkdir -p -- "$build/lib/NLS/$namespace"
  for entry in "$reference/.lake/build/lib/lean/NLS/$namespace/"*; do
    [[ -e "$entry" ]] || continue
    name="${entry##*/}"
    if [[ ! -e "$build/lib/NLS/$namespace/$name" ]]; then
      ln -s -- "$entry" "$build/lib/NLS/$namespace/$name"
    fi
  done
done
# Only specific Lean output paths below are writable build targets. Generic
# namespace links are imports; this directory must never be used by lake build.
for entry in "$reference/.lake/build/lib/lean/NLS/"*; do
  name="$(basename -- "$entry")"
  if [[ "$name" != Articles && ! -e "$build/lib/NLS/$name" ]]; then
    ln -s -- "$entry" "$build/lib/NLS/$name"
  fi
done
import_paths=("$build/lib" "$reference/.lake/build/lib/lean")
for dependency in "$reference"/.lake/packages/*/.lake/build/lib/lean; do
  [[ -d "$dependency" ]] && import_paths+=("$dependency")
done
export LEAN_PATH
LEAN_PATH="$(IFS=:; echo "${import_paths[*]}")"
# Mirror read-only mathlib imports into a private tree so the additional
# pinned Arsinh module can be compiled without writing into the reference.
python3 - "$reference/.lake/packages/mathlib/.lake/build/lib/lean/Mathlib" "$build/lib/Mathlib" <<'PYMATHLIB'
from pathlib import Path
import sys
src,dst=map(Path,sys.argv[1:])
if dst.is_symlink():
    raise SystemExit(f'Refusing output through linked mathlib root: {dst}')
for p in src.rglob('*'):
    q=dst/p.relative_to(src)
    if p.is_dir():
        if q.is_symlink():
            raise SystemExit(f'Refusing output through linked directory: {q}')
        q.mkdir(parents=True,exist_ok=True)
    elif not q.exists() and not q.is_symlink():
        q.symlink_to(p)
PYMATHLIB
mathlib_arsinh="$build/lib/Mathlib/Analysis/SpecialFunctions/Arsinh.olean"
if [[ -L "$mathlib_arsinh" ]]; then unlink -- "$mathlib_arsinh"; fi
(cd -- "$reference/.lake/packages/mathlib" &&
  "$lean_bin" -DwarningAsError=true -o "$mathlib_arsinh" Mathlib/Analysis/SpecialFunctions/Arsinh.lean) \
  > "$build/logs/Mathlib.Analysis.SpecialFunctions.Arsinh.log" 2>&1 || {
    cat -- "$build/logs/Mathlib.Analysis.SpecialFunctions.Arsinh.log"; exit 1;
  }
echo 'Checked pinned Mathlib.Analysis.SpecialFunctions.Arsinh (private output)'
cd -- "$repo"
for module in ComplexAnalysis/AnalyticUnitDerivativeInverse ComplexAnalysis/AnalyticOpenInverse ComplexAnalysis/SmallQuadraticInverse SequenceSpaces/PeriodOneMassResolvent SequenceSpaces/PeriodOneMiuraQuadratic SequenceSpaces/PeriodOneMiuraCharts SequenceSpaces/PeriodOneMiuraRegularity SequenceSpaces/PeriodOneMiuraShift ComplexAnalysis/AnalyticLocalLipschitz ComplexAnalysis/NormalizedSquareRootBounds ComplexAnalysis/LogarithmStripNormalization ComplexAnalysis/TwoZeroDeflation ComplexAnalysis/AnalyticDiscSquareRoot ComplexAnalysis/AnalyticTwoZeroRoot ComplexAnalysis/SquaredCircleHomotopy ComplexAnalysis/AnalyticCutContour ComplexAnalysis/QuadraticRootContourPeriod ZakharovShabat/ContinuousPotentialL2Bound ZakharovShabat/ClassicalSolutionInjectivity KdV/RiccatiEnergy KdV/ConstantUpperSpectralBridge KdV/ClassicalSpectralSymmetry KdV/ClassicalDiscriminant KdV/ClassicalLocalPrimitive KdV/ClassicalFreePrimitive KdV/ClassicalHillFlow KdV/ClassicalHillSpectrum KdV/ClassicalHillGreen KdV/ClassicalSourcePrimitive KdV/ClassicalSpectralEmbedding KdV/ClassicalContourCoverage KdV/ClassicalHighGapPairs KdV/ClassicalHillReality KdV/ClassicalHillConjugation KdV/ClassicalHillPrimitiveSheets KdV/ClassicalHillPrimitiveReflection KdV/ClassicalHillBandNormalization KdV/ClassicalHillDiscAsymptotics KdV/ClassicalHillHighTracePhase KdV/ClassicalHillHighPrimitiveStrip KdV/ClassicalHillHighEndpointNormalization KdV/ClassicalBranchPrimitive KdV/ClassicalHillSquaredPrimitiveMatching KdV/ClassicalCoshStripControl KdV/ClassicalHillSmallDiscTrace KdV/ClassicalHillSmallGapCoverage KdV/ClassicalHillAnnulusCoverage KdV/ClassicalHillWholeGapSquares KdV/ClassicalHillFreeSquareComparison KdV/ClassicalHillGapQuotients KdV/ClassicalHillGapScaleBounds KdV/ClassicalHillGapCutRoots KdV/ClassicalTraceAsymptotics KdV/ActionHamiltonianMoments KdV/ClassicalContourMoments KdV/ClassicalHighContourMoments KdV/ClassicalHillMomentReality KdV/ClassicalHighGapFamilies KdV/ClassicalHillGapQuotientAsymptotics KdV/Classic